/// <summary>
/// MPJ_2864 - kscerri - 22/03/2021
/// Subtask class created to process all sub task process
/// </summary>
public class METPopulateCustCreditLimitSubTaskService
{
}

Method.Source:
    /// <summary>
    /// MPJ_2864 - kscerri - 22/03/2021
    /// processSubTask contains the business logic to create/update according to the task and its parameters
    /// </summary>
    /// <param name = "_dataContract">Contract contains the custAccount list required per task</param>
    public void processSubTask(METPopulateCustCreditLimitContract _dataContract)
    {
        CustTable                           custTable;
        METCustCreditLimit                  metCustCreditLimit;
        METCustTable                        metCustTable;
        AmountMST                           balance;
        METPopulateCustCreditLimitService   populateCustCreditLimitService = new METPopulateCustCreditLimitService();
        List                                custAccounts                   = new List(Types::String);
        ListEnumerator                      enumerator;


        custAccounts    = _dataContract.getCustAccountList();
        enumerator      = custAccounts.getEnumerator();

        while (enumerator.moveNext())
        {
            select firstonly CreditMax, AccountNum, CredManAccountStatusId, DefaultDimension from custTable
                where custTable.AccountNum == enumerator.current()
                outer join firstonly AMEXBalance
                    from metCustTable
                    where metCustTable.AccountNum == custTable.AccountNum
                outer join firstonly metCustCreditLimit
                    where metCustCreditLimit.AccountNum == custTable.AccountNum;
            
            balance = populateCustCreditLimitService.getBalance(custTable.AccountNum);

            metCustCreditLimit.Balance          = balance + metCustTable.AMEXBalance;
            metCustCreditLimit.CreditLimit      = custTable.CreditMax;
            metCustCreditLimit.CreditStatus     = custTable.CredManAccountStatusId;
            if(metCustCreditLimit.DefaultDimension != custTable.DefaultDimension)
            {
                // Update State & Pillar values
                metCustCreditLimit.State        = METHelper::getDimensionValue(custTable.DefaultDimension, METConstants::state);
                metCustCreditLimit.Pillar       = METHelper::getDimensionValue(custTable.DefaultDimension, METConstants::pillar);
                metCustCreditLimit.ProfitCentre = METHelper::getDimensionValue(custTable.DefaultDimension, METConstants::profitCentre);
            }
            metCustCreditLimit.DefaultDimension = custTable.DefaultDimension;
                
            if (!metCustCreditLimit.RecId)
            {
                metCustCreditLimit.AccountNum       = custTable.AccountNum;
                metCustCreditLimit.insert();
            }
            else if(metCustCreditLimit.Balance != metCustCreditLimit.orig().Balance
                    || metCustCreditLimit.CreditLimit   != metCustCreditLimit.orig().CreditLimit
                    || metCustCreditLimit.CreditStatus  != metCustCreditLimit.orig().CreditStatus
                    || metCustCreditLimit.State         != metCustCreditLimit.orig().State
                    || metCustCreditLimit.Pillar        != metCustCreditLimit.orig().Pillar
                    || metCustCreditLimit.ProfitCentre  != metCustCreditLimit.orig().ProfitCentre)
            {
                ttsbegin;
                metCustCreditLimit.selectForUpdate(true);
                metCustCreditLimit.update();
                ttscommit;
            }
        }
    }
